<?php $pageTitle='Leaderboard';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/../includes/sidebar.php';$db=getDB();$club=$_SESSION['club_id'];$period=$_GET['period']??'weekly';$metric=$_GET['metric']??'spent';$from=$period==='daily'?'CURDATE()':($period==='monthly'?"DATE_FORMAT(CURDATE(),'%Y-%m-01')":($period==='alltime'?"'2000-01-01'":"DATE_SUB(CURDATE(),INTERVAL 7 DAY)"));$value=$metric==='hours'?'SUM(TIMESTAMPDIFF(SECOND,s.start_time,s.end_time)-s.total_pause_seconds)/3600':($metric==='frames'?'SUM(s.frames_played)':($metric==='visits'?'COUNT(s.id)':'SUM(s.total_amount)'));$q=$db->prepare("SELECT p.*, $value value FROM players p JOIN sessions s ON s.player_id=p.id WHERE p.club_id=? AND s.status='completed' AND DATE(s.end_time) >= $from GROUP BY p.id ORDER BY value DESC LIMIT 50");$q->execute([$club]);$rows=$q->fetchAll();?><h1 class="text-2xl font-bold">Leaderboard</h1><form class="card mt-5 flex gap-3"><select name="period" class="input w-44"><?php foreach(['daily'=>'Today','weekly'=>'This Week','monthly'=>'This Month','alltime'=>'All Time'] as $v=>$l):?><option <?=$period===$v?'selected':''?> value="<?=$v?>"><?=$l?></option><?php endforeach?></select><select name="metric" class="input w-44"><?php foreach(['spent'=>'Most Spent','hours'=>'Most Hours','frames'=>'Most Frames','visits'=>'Most Visits'] as $v=>$l):?><option <?=$metric===$v?'selected':''?> value="<?=$v?>"><?=$l?></option><?php endforeach?></select><button class="btn-primary">Update</button></form><section class="card mt-5 overflow-x-auto"><table class="data-table w-full"><thead><tr><th>Rank</th><th>Player</th><th>Tier</th><th>Value</th></tr></thead><tbody><?php foreach($rows as $i=>$p):?><tr class="<?=$i<3?'bg-amber-500/5':''?>"><td class="font-bold <?=$i===0?'text-amber-300':''?>">#<?=$i+1?></td><td><?=sanitize($p['name'])?></td><td><?=ucfirst($p['tier'])?></td><td class="text-green-400 font-semibold"><?=$metric==='spent'?money($p['value']):round($p['value'],1)?></td></tr><?php endforeach?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
